 void Settings() {var settingsContent=new StackPanel();this.list.Children.Add(new GlassSurface(Wallpaper) {Content=settingsContent,Padding=new Thickness(22)});var list=settingsContent;list.Children.Add(new PreferencesPanel(app));var sound=new CheckBox {Content="完成待办时播放轻提示音",IsChecked=app.Store.Data.Sound,Margin=new Thickness(0,10,0,20)};sound.Click+=(s,e)=>{app.Store.Data.Sound=sound.IsChecked==true;app.Save();};list.Children.Add(sound);var startup=new CheckBox {Content="登录 Windows 后自动启动",IsChecked=AutoStart.Enabled(),Margin=new Thickness(0,0,0,25)};startup.Click+=(s,e)=>{try{AutoStart.Set(startup.IsChecked==true);}catch(Exception ex){startup.IsChecked=AutoStart.Enabled();MessageBox.Show(ex.Message,"无法修改开机启动");}};list.Children.Add(startup);list.Children.Add(UI.Text("数据保存位置",15,UI.Ink));var path=new TextBox {Text=app.Store.Root,IsReadOnly=true,Margin=new Thickness(0,8,0,20)};list.Children.Add(path);var buttons=new WrapPanel();buttons.Children.Add(UI.Button("导出完整备份",()=>{var d=new SaveFileDialog {Filter="NoteDesk 备份 (*.json)|*.json",FileName="NoteDesk-backup-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+".json"};if(d.ShowDialog(this)==true){foreach(var w in app.OpenNotes.Values)w.Flush();File.WriteAllText(d.FileName,Store.Json.Serialize(app.Store.Data),Encoding.UTF8);MessageBox.Show("备份已导出，包含所有便签与历史版本。","NoteDesk");}}));buttons.Children.Add(UI.Button("导入备份",Import));foreach(Button action in buttons.Children)action.Margin=new Thickness(0,0,8,6);list.Children.Add(buttons);var tips=UI.Text("使用小贴士\n\n• 拖动便签顶部的 NOTEDESK 区域移动窗口，右下角可缩放。\n• 待办右侧的 ··· 可编辑内容、设置截止与提醒。\n• 便签菜单可换色、调透明度、查看历史或归档。\n• 关闭窗口只隐藏，托盘菜单可新建、管理或退出。\n• 软件退出时无法发出提醒，启动后会补提示。\n• 归档便签恢复后保留完成状态，旧提醒不会再次触发。",12,UI.Muted);tips.Margin=new Thickness(0,30,0,0);list.Children.Add(tips);}
 void Import(){var d=new OpenFileDialog {Filter="NoteDesk 备份 (*.json)|*.json"};if(d.ShowDialog(this)!=true)return;try{var imported=Store.Json.Deserialize<Database>(File.ReadAllText(d.FileName,Encoding.UTF8));if(imported==null||imported.Schema!=1||imported.Notes==null)throw new InvalidDataException();foreach(var n in imported.Notes){if(n.Tasks==null||n.History==null)throw new InvalidDataException();}if(MessageBox.Show("将备份合并到现有便签；相同编号的记录会跳过，现有内容保留。继续吗？","导入备份",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;int count=0;foreach(var n in imported.Notes)if(!app.Store.Data.Notes.Any(x=>x.Id==n.Id)){n.Visible=false;app.Store.Data.Notes.Add(n);count++;}app.Save();app.Status("已导入 "+count+" 张便签");}catch{MessageBox.Show("无法读取这份备份，现有便签未被覆盖。","导入失败");}}
