public static class Program {
 [STAThread] public static int Main(string[] args) {string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"NoteDesk");for(int i=0;i<args.Length-1;i++)if(args[i]=="--data-root")root=Path.GetFullPath(args[i+1]);if((args.Contains("--self-test")||args.Contains("--preview")||args.Contains("--integration-test"))&&!args.Contains("--data-root")){MessageBox.Show("测试模式必须指定独立的 --data-root 目录。");return 2;}if(args.Contains("--render-preview")){if(!args.Contains("--data-root"))return 2;string appearance="system";for(int i=0;i<args.Length-1;i++)if(args[i]=="--appearance")appearance=args[i+1];return Tests.RenderPreview(root,appearance);}if(args.Contains("--self-test"))return Tests.Run(root);if(args.Contains("--integration-test"))return Tests.Integration(root,args.Contains("--headless"));
 bool preview=args.Contains("--preview");bool acquired;using(var mutex=new System.Threading.Mutex(true,"Local\\NoteDesk-"+StableKey(root),out acquired)){if(!acquired){MessageBox.Show("NoteDesk 已在运行，请从系统托盘打开。","NoteDesk");return 0;}try{var app=new DeskApp(root,preview);app.DispatcherUnhandledException+=(s,e)=>{File.AppendAllText(Path.Combine(root,"error.log"),DateTime.Now+" "+e.Exception+"\n");MessageBox.Show("遇到一个问题，详细记录已保存至数据目录。\n"+e.Exception.Message,"NoteDesk");e.Handled=true;};app.Start();if(preview){var timer=new DispatcherTimer {Interval=TimeSpan.FromSeconds(1)};timer.Tick+=(s,e)=>{timer.Stop();Capture(app.Manager,Path.Combine(root,"manager.png"));foreach(var w in app.OpenNotes.Values)Capture(w,Path.Combine(root,"note.png"));app.Quit();};timer.Start();}return app.Run();}catch(Exception ex){MessageBox.Show(ex.Message,"NoteDesk 无法启动");return 1;}} }
 static string StableKey(string value){using(var sha=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(value.ToLowerInvariant()))).Replace("-","").Substring(0,20);}
 public static void Capture(Window w,string file){var target=new RenderTargetBitmap((int)w.ActualWidth,(int)w.ActualHeight,96,96,PixelFormats.Pbgra32);target.Render(w);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(target));using(var f=File.Create(file))encoder.Save(f);}
}
public static class Tests {
 public static int RenderPreview(string root,string appearance="system") { try {Run(root);var app=new DeskApp(root,true);UI.ApplyAppearance(appearance);app.Manager=new Manager(app);Render(app.Manager,Path.Combine(root,"manager.png"));var note=new NoteWindow(app,app.Store.Data.Notes.First(n=>n.State=="active"));Render(note,Path.Combine(root,"note.png"));note.Width=300;Render(note,Path.Combine(root,"note-narrow.png"));foreach(var section in new[]{"archived","deleted","settings"}){app.Manager.PreviewSection(section);Render(app.Manager,Path.Combine(root,section+".png"));}var target=app.Store.Data.Notes[0];Render(new TaskDialog(target.Tasks[0],null),Path.Combine(root,"task-dialog.png"));Render(new HistoryWindow(app,target,null),Path.Combine(root,"history.png"));Render(new ReminderWindow(app,new List<Tuple<Note,TaskItem>>{Tuple.Create(target,target.Tasks[0])}),Path.Combine(root,"reminder.png"));Render(new UndoToast(app,"今天的小事",()=>{}),Path.Combine(root,"toast.png"));var stress=new Note {Title=string.Concat(Enumerable.Repeat("一个很长的标题与今天的想法",12)),Body=string.Concat(Enumerable.Repeat("长正文应该在内容区内滚动，添加待办始终可见。\n",15)),W=300,H=380};for(int i=0;i<12;i++)stress.Tasks.Add(new TaskItem {Text="第 "+(i+1)+" 项：在小窗口下也能完整阅读的长待办文字与提醒"});var compact=new NoteWindow(app,stress);Render(compact,Path.Combine(root,"note-compact-long.png"));var input=(FrameworkElement)FindNamed((DependencyObject)compact.Content,"待办内容");Assert(input!=null&&input.ActualWidth>100,"compact note retains usable input width");var inputBottom=input.TransformToAncestor((Visual)compact.Content).Transform(new Point(0,input.ActualHeight));Assert(inputBottom.Y<compact.Height-35,"compact note input stays inside window");app.Store.Data.Notes.Add(stress);app.Manager.Width=820;app.Manager.Height=540;app.Manager.PreviewSection("active");Render(app.Manager,Path.Combine(root,"manager-compact-long.png"));app.Manager.PreviewSection("settings");Render(app.Manager,Path.Combine(root,"settings-compact.png"));app.Store.Data.Notes.Remove(stress);File.WriteAllText(Path.Combine(root,"render-results.txt"),"PASS: all screens rendered offscreen; compact note input bounds; long text and compact manager/settings",Encoding.UTF8);app.Shutdown();return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(root,"render-results.txt"),ex.ToString(),Encoding.UTF8);return 1;} }
 static void Render(Window window,string file) {var content=(FrameworkElement)window.Content;var size=new Size(window.Width,window.Height);var scene=content as WallpaperScene;if(scene!=null)scene.Prepare(size);content.Measure(size);content.Arrange(new Rect(size));content.UpdateLayout();var bitmap=new RenderTargetBitmap((int)size.Width,(int)size.Height,96,96,PixelFormats.Pbgra32);var background=new DrawingVisual();using(var dc=background.RenderOpen())dc.DrawRectangle(window.Background,null,new Rect(size));bitmap.Render(background);bitmap.Render(content);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(file))encoder.Save(stream);}
 static void VerifyMotion(DeskApp app,string root) {using(var inputSource=new System.Windows.Interop.HwndSource(new System.Windows.Interop.HwndSourceParameters("NoteDesk offscreen input") {Width=1,Height=1,WindowStyle=0,ParentWindow=new IntPtr(-3)})){var n=new Note {Title="Motion verification",Visible=false};n.Tasks.Add(new TaskItem {Text="Keyboard completion"});n.Tasks.Add(new TaskItem {Text="Mouse completion"});app.Store.Data.Notes.Add(n);var window=new NoteWindow(app,n);Render(window,Path.Combine(root,"motion-window.png"));var button=FindComplete((DependencyObject)window.Content);button.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,inputSource,0,Key.Space) {RoutedEvent=UIElement.PreviewKeyDownEvent});Assert(!UI.MotionAllowed,"keyboard suppresses animation");button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Assert(n.Tasks[0].Done,"keyboard completion updates immediately");Render(window,Path.Combine(root,"motion-keyboard.png"));button=FindComplete((DependencyObject)window.Content);button.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice,0,MouseButton.Left) {RoutedEvent=UIElement.PreviewMouseDownEvent});button.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice,0,MouseButton.Left) {RoutedEvent=UIElement.PreviewMouseLeftButtonDownEvent});Assert(UI.MotionAllowed==SystemParameters.ClientAreaAnimation,"mouse respects system animation preference");button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Assert(n.Tasks.All(t=>t.Done),"mouse completion updates immediately");if(SystemParameters.ClientAreaAnimation)Assert(!button.IsEnabled,"mouse completion uses short feedback");app.CancelArchive(n);app.Store.Data.Notes.Remove(n);window.Close();}}
 static DependencyObject FindNamed(DependencyObject parent,string name) {if(System.Windows.Automation.AutomationProperties.GetName(parent)==name)return parent;for(int i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++){var found=FindNamed(VisualTreeHelper.GetChild(parent,i),name);if(found!=null)return found;}return null;}
 static Button FindComplete(DependencyObject parent){var button=parent as Button;if(button!=null&&button.Tag as string=="complete-task"&&System.Windows.Automation.AutomationProperties.GetName(button).StartsWith("完成：",StringComparison.Ordinal))return button;for(int i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++){var found=FindComplete(VisualTreeHelper.GetChild(parent,i));if(found!=null)return found;}return null;}

 public static int Integration(string root,bool headless=false) {var app=new DeskApp(root,true);app.Headless=headless;Note target=null;int code=1;try {app.Start();Assert(app.Manager.Foreground==UI.Ink,"shared theme applied to derived windows");if(headless)VerifyMotion(app,root);target=app.NewNote();target.Title="Integration test";target.Tasks.Add(new TaskItem {Text="Finish me"});app.Changed(target);app.RefreshNote(target);app.HideNote(target);Assert(!target.Visible,"hide preserves note");app.ShowNote(target);Assert(target.Visible,"show restores visibility");if(headless)Render(app.OpenNotes[target.Id],Path.Combine(root,"integration-window.png"));else app.OpenNotes[target.Id].UpdateLayout();var completion=FindComplete((DependencyObject)app.OpenNotes[target.Id].Content);Assert(completion!=null,"completion button exists");completion.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Assert(target.PendingArchive,"pending archive saved");var timer=new DispatcherTimer {Interval=TimeSpan.FromSeconds(4)};timer.Tick+=(s,e)=>{timer.Stop();try{Assert(target.State=="archived","automatic archive after 3 seconds");Assert(!app.OpenNotes[target.Id].IsVisible,"archived window hidden");app.UndoAction();Assert(target.State=="active"&&!target.Tasks[0].Done,"undo restores final unchecked task");Assert(!target.PendingArchive,"undo clears pending");app.Delete(target);Assert(target.State=="deleted","soft delete");app.Restore(target);Assert(target.State=="active","recycle restore");target.Tasks[0].Done=true;app.Archive(target,null);app.Restore(target);Assert(!target.PendingArchive,"restored archive remains on desktop");var saved=new Store(root).Data.Notes.First(n=>n.Id==target.Id);Assert(saved.State=="active"&&saved.Tasks[0].Done,"restored completed state persisted");new TaskDialog(target.Tasks[0],headless?null:app.Manager).Close();new HistoryWindow(app,target,headless?null:app.Manager).Close();var reminder=new ReminderWindow(app,new List<Tuple<Note,TaskItem>> {Tuple.Create(target,target.Tasks[0])});reminder.Close();File.WriteAllText(Path.Combine(root,"integration-results.txt"),"PASS: window theme, keyboard/mouse motion policy, windows, hide/show, timed autoarchive, undo, recycle restore, archived restore, settings/history/reminder dialog construction",Encoding.UTF8);code=0;}catch(Exception ex){File.WriteAllText(Path.Combine(root,"integration-results.txt"),"FAIL: "+ex,Encoding.UTF8);}finally{app.Quit();}};timer.Start();app.Run();}catch(Exception ex){File.WriteAllText(Path.Combine(root,"integration-results.txt"),"FAIL: "+ex,Encoding.UTF8);}return code;
 }

 static void Assert(bool yes,string name){if(!yes)throw new Exception(name);}
 public static int Run(string root){try{Directory.CreateDirectory(root);var s=new Store(root);s.Data=new Database();var n=new Note {Title="把今天，过成喜欢的样子",Body="不用一口气完成所有事。\n每向前一步，都算数。",X=160,Y=130,Color=0};n.Tasks.Add(new TaskItem {Text="给自己留一段专注的时间",Done=true});n.Tasks.Add(new TaskItem {Text="整理今天的灵感与随手记"});n.Tasks.Add(new TaskItem {Text="完成第一件真正重要的小事",Due=DateTime.Now.AddHours(2).ToString("o")});s.Data.Notes.Add(n);s.Snapshot(n);n.Body+="\n\n愿这里，装得下你的每一个小小念头。";s.Snapshot(n);s.Save();var loaded=new Store(root);Assert(loaded.Data.Notes[0].Tasks.Count==3,"round trip tasks");Assert(loaded.Data.Notes[0].History.Count==2,"history persisted");Assert(File.Exists(Path.Combine(root,"notes.json")),"save exists");loaded.Save();Assert(File.Exists(Path.Combine(root,"notes.json.bak")),"atomic backup");var old=n.History[0];s.Restore(n,old);Assert(n.History.Count==3,"restore retains history");Assert(!n.Body.Contains("小小念头"),"restore content");var t=new TaskItem {Due=DateTime.Now.AddMinutes(20).ToString("o"),Lead=30};Assert(Store.NeedsReminder(t,DateTime.Now),"advance reminder");t.Reminded=true;Assert(!Store.NeedsReminder(t,DateTime.Now),"no duplicate");t.Reminded=false;t.Done=true;Assert(!Store.NeedsReminder(t,DateTime.Now),"completed silent");t.Done=false;t.Snooze=DateTime.Now.AddMinutes(10).ToString("o");Assert(!Store.NeedsReminder(t,DateTime.Now),"snooze");t.Snooze=DateTime.Now.AddMinutes(-1).ToString("o");Assert(Store.NeedsReminder(t,DateTime.Now),"snooze due");t.Due=DateTime.Now.AddDays(-2).ToString("o");t.Snooze=null;Assert(Store.NeedsReminder(t,DateTime.Now),"missed reminders");
 var archived=new Note {Title="那些完成过的小事",Body="今天把搁置很久的事情做完了。\n原来慢一点，也能到达。",State="archived",Archived=DateTime.Now.AddDays(-1).ToString("o"),Visible=false,Color=1};archived.Tasks.Add(new TaskItem {Text="迈出第一步",Done=true});s.Snapshot(archived);s.Data.Notes.Add(archived);s.Save();File.WriteAllText(Path.Combine(root,"test-results.txt"),"PASS: persistence, history, restore, atomic backup, advance reminders, deduplication, completed silence, snooze, missed reminders\n",Encoding.UTF8);return 0;
 }catch(Exception ex){File.WriteAllText(Path.Combine(root,"test-results.txt"),"FAIL: "+ex,Encoding.UTF8);return 1;}}
}
